import { CommonModule } from '@angular/common';
import { Component } from '@angular/core';
import { ActivatedRoute, RouterLink } from '@angular/router';

@Component({
  selector: 'app-inscricao-sucesso',
  standalone: true,
  imports: [
    CommonModule,
    RouterLink
  ],
  templateUrl: './inscricao-sucesso.page.html',
  styleUrls: ['./inscricao-sucesso.page.scss']
})
export class InscricaoSucessoPageComponent {

  votacao = '';

  constructor(
    private readonly route: ActivatedRoute
  ) {

    this.votacao =
      this.route.snapshot.queryParamMap.get('votacao')
      ?? '';
  }
}